begin;
create table if not exists public.product_categories(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,name text not null,active boolean not null default true,unique(company_id,name));
create table if not exists public.products(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,category_id uuid references public.product_categories(id) on delete set null,sku text,name text not null,unit text not null default 'ud',current_cost numeric(12,4) not null default 0,min_stock numeric(12,3) not null default 0,active boolean not null default true,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(company_id,name));
create table if not exists public.warehouses(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,restaurant_id uuid not null references public.restaurants(id) on delete cascade,name text not null,location text,active boolean not null default true,unique(restaurant_id,name));
create table if not exists public.stock_levels(id uuid primary key default gen_random_uuid(),warehouse_id uuid not null references public.warehouses(id) on delete cascade,product_id uuid not null references public.products(id) on delete cascade,quantity numeric(12,3) not null default 0,updated_at timestamptz not null default now(),unique(warehouse_id,product_id));
create table if not exists public.stock_movements(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,restaurant_id uuid not null references public.restaurants(id) on delete cascade,warehouse_id uuid not null references public.warehouses(id),product_id uuid not null references public.products(id),movement_type text not null check(movement_type in('receipt','adjustment','transfer_in','transfer_out','waste','consumption')),quantity numeric(12,3) not null,unit_cost numeric(12,4),reference text,notes text,created_at timestamptz not null default now());
create table if not exists public.inventory_counts(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,restaurant_id uuid not null references public.restaurants(id) on delete cascade,warehouse_id uuid not null references public.warehouses(id),count_date date not null default current_date,status text not null default 'draft' check(status in('draft','counting','reviewed','closed')),notes text,created_at timestamptz not null default now());
create table if not exists public.inventory_count_lines(id uuid primary key default gen_random_uuid(),inventory_count_id uuid not null references public.inventory_counts(id) on delete cascade,product_id uuid not null references public.products(id),expected_quantity numeric(12,3) not null default 0,counted_quantity numeric(12,3),unique(inventory_count_id,product_id));
create table if not exists public.waste_records(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,restaurant_id uuid not null references public.restaurants(id) on delete cascade,warehouse_id uuid not null references public.warehouses(id),product_id uuid not null references public.products(id),quantity numeric(12,3) not null,reason text not null,cost numeric(12,2),occurred_at timestamptz not null default now(),notes text);
alter table public.product_categories enable row level security;alter table public.products enable row level security;alter table public.warehouses enable row level security;alter table public.stock_levels enable row level security;alter table public.stock_movements enable row level security;alter table public.inventory_counts enable row level security;alter table public.inventory_count_lines enable row level security;alter table public.waste_records enable row level security;
do $$ declare t text;begin foreach t in array array['product_categories','products','warehouses','stock_movements','inventory_counts','waste_records'] loop execute format('drop policy if exists company_members_access on public.%I',t);execute format('create policy company_members_access on public.%I for all to authenticated using(exists(select 1 from public.company_members cm where cm.company_id=%I.company_id and cm.user_id=auth.uid())) with check(exists(select 1 from public.company_members cm where cm.company_id=%I.company_id and cm.user_id=auth.uid()))',t,t,t);end loop;end $$;
drop policy if exists stock_levels_access on public.stock_levels;create policy stock_levels_access on public.stock_levels for all to authenticated using(exists(select 1 from public.warehouses w join public.company_members cm on cm.company_id=w.company_id where w.id=warehouse_id and cm.user_id=auth.uid())) with check(exists(select 1 from public.warehouses w join public.company_members cm on cm.company_id=w.company_id where w.id=warehouse_id and cm.user_id=auth.uid()));
drop policy if exists inventory_count_lines_access on public.inventory_count_lines;create policy inventory_count_lines_access on public.inventory_count_lines for all to authenticated using(exists(select 1 from public.inventory_counts i join public.company_members cm on cm.company_id=i.company_id where i.id=inventory_count_id and cm.user_id=auth.uid())) with check(exists(select 1 from public.inventory_counts i join public.company_members cm on cm.company_id=i.company_id where i.id=inventory_count_id and cm.user_id=auth.uid()));
grant select,insert,update,delete on public.product_categories,public.products,public.warehouses,public.stock_levels,public.stock_movements,public.inventory_counts,public.inventory_count_lines,public.waste_records to authenticated;
commit;
